// AUTOGENERATED by yintercept_generator.py
import 'dart:math';
import 'fraction.dart';
import 'yi_steps.dart';

// ── Constants ────────────────────────────────────────────────────────

const zeroFrac = YIFraction(numerator: 0, denominator: 1);
const oneFrac = YIFraction(numerator: 1, denominator: 1);
const negOneFrac = YIFraction(numerator: -1, denominator: 1);

// ── LaTeX Helpers ────────────────────────────────────────────────────

String fracLatex(YIFraction f) {
  final s = f.simplified();
  if (s.denominator == 1) return '${s.numerator}';
  return s.numerator < 0
      ? '-\\frac{${s.numerator.abs()}}{${s.denominator}}'
      : '\\frac{${s.numerator}}{${s.denominator}}';
}

String boxLatex(String inner) => '\\boxed{$inner}';

String textLatex(String t) {
  return '\\text{${t.replaceAll('{', r'\{').replaceAll('}', r'\}').replaceAll(r'\', r'\\').replaceAll('%', r'\%')}}';
}

String mxLatex(YIFraction m) {
  final s = m.simplified();
  if (s == oneFrac) return 'x';
  if (s == negOneFrac) return '-x';
  return '${fracLatex(s)}x';
}

String eqLatex(YIFraction m, YIFraction b) {
  final ms = m.simplified(), bs = b.simplified();
  if (ms.isZero) return 'y = ${fracLatex(bs)}';
  final mp = mxLatex(ms);
  if (bs.isZero) return 'y = $mp';
  return bs.numerator > 0 ? 'y = $mp + ${fracLatex(bs)}' : 'y = $mp - ${fracLatex(bs.abs())}';
}

String sfLatex(int A, int B, int C) {
  String t(int c, String v, bool first) {
    if (c == 0) return '';
    final a = c.abs(), vs = a == 1 ? v : '$a$v';
    if (first) return c < 0 ? '-$vs' : vs;
    return c < 0 ? '- $vs' : '+ $vs';
  }
  return '${t(A, 'x', true)} ${t(B, 'y', false)} = $C'.trim();
}

String gfLatex(int A, int B, int C) {
  String t(int c, String v, bool first) {
    if (c == 0) return '';
    final a = c.abs(), vs = a == 1 ? v : '$a$v';
    if (first) return c < 0 ? '-$vs' : vs;
    return c < 0 ? '- $vs' : '+ $vs';
  }
  final xp = t(A, 'x', true), yp = t(B, 'y', false);
  final cp = C > 0 ? '+ $C' : C < 0 ? '- ${C.abs()}' : '';
  return '${[xp, yp, cp].where((s) => s.isNotEmpty).join(' ')} = 0';
}

String termLatex(int c, String v, {required bool isFirst}) {
  if (c == 0) return '';
  final a = c.abs(), vs = a == 1 ? v : '$a$v';
  return isFirst ? (c < 0 ? '-$vs' : vs) : (c < 0 ? '- $vs' : '+ $vs');
}

String termStr(int c, String v, {required bool isFirst}) => termLatex(c, v, isFirst: isFirst);

String rhsAfterMovingXLatex(int A, int B, int C) {
  final y = B == 1 ? 'y' : B == -1 ? '-y' : '${B}y';
  return '$y = $C ${A > 0 ? '-' : '+'} ${A.abs() == 1 ? 'x' : '${A.abs()}x'}';
}

String direction(double m) =>
    m > 0 ? 'Rising \u2197' : m < 0 ? 'Falling \u2198' : 'Horizontal \u2192';

String riseRun(YIFraction m) {
  final s = m.simplified();
  return s.denominator == 1 ? '${s.numerator} / 1' : '${s.numerator} / ${s.denominator}';
}

// ── Form Conversion Helpers ─────────────────────────────────────────

int lcm(int a, int b) => a == 0 || b == 0 ? 1 : (a * b).abs() ~/ _gcd2(a.abs(), b.abs());

int _gcd2(int a, int b) { while (b != 0) { final t = b; b = a % b; a = t; } return a; }

int gcd3(int a, int b, int c) => _gcd2(_gcd2(a, b), c);

String sfString(int A, int B, int C) {
  final x = termStr(A, 'x', isFirst: true);
  final y = termStr(B, 'y', isFirst: false);
  return '$x $y = $C'.replaceAll('  ', ' ').trim();
}

String gfString(int A, int B, int C) {
  final xp = termStr(A, 'x', isFirst: true);
  final yp = termStr(B, 'y', isFirst: false);
  final cp = C > 0 ? '+ $C' : C < 0 ? '- ${C.abs()}' : '';
  return '${[xp, yp, cp].where((s) => s.isNotEmpty).join(' ')} = 0';
}

String generalFormFromABC(int A, int B, int C) => gfString(A, B, -C);

String standardFormFromSlopeIntercept(YIFraction m, YIFraction b) {
  if (m.isZero) return 'y = ${fracLatex(b)}';
  final s = lcm(m.denominator, b.denominator);
  final A = -(m.numerator * (s ~/ m.denominator));
  final C = b.numerator * (s ~/ b.denominator);
  final g = gcd3(A.abs(), s, C.abs());
  return sfString(A ~/ g, s ~/ g, C ~/ g);
}

String generalFormFromSlopeIntercept(YIFraction m, YIFraction b) {
  if (m.isZero) {
    final nb = -b.numerator;
    return b.denominator == 1
        ? 'y ${nb >= 0 ? '+ $nb' : '- ${nb.abs()}'} = 0'
        : 'y + ${YIFraction(numerator: nb, denominator: b.denominator).simplified()} = 0';
  }
  final s = lcm(m.denominator, b.denominator);
  final A = -(m.numerator * (s ~/ m.denominator));
  final C = -(b.numerator * (s ~/ b.denominator));
  final g = gcd3(A.abs(), s, C.abs());
  return gfString(A ~/ g, s ~/ g, C ~/ g);
}

String sfTexFromSlopeIntercept(YIFraction m, YIFraction b) {
  if (m.isZero) return 'y = ${fracLatex(b)}';
  final s = lcm(m.denominator, b.denominator);
  final A = -(m.numerator * (s ~/ m.denominator));
  final C = b.numerator * (s ~/ b.denominator);
  final g = gcd3(A.abs(), s, C.abs());
  return sfLatex(A ~/ g, s ~/ g, C ~/ g);
}

String gfTexFromSlopeIntercept(YIFraction m, YIFraction b) {
  if (m.isZero) {
    final nb = -b.numerator;
    return 'y ${nb >= 0 ? '+' : '-'} ${nb.abs()} = 0';
  }
  final s = lcm(m.denominator, b.denominator);
  final A = -(m.numerator * (s ~/ m.denominator));
  final C = -(b.numerator * (s ~/ b.denominator));
  final g = gcd3(A.abs(), s, C.abs());
  return gfLatex(A ~/ g, s ~/ g, C ~/ g);
}

// ── Fraction Parser ──────────────────────────────────────────────────

YIFraction? parseFractionString(String text) {
  text = text.trim().replaceAll('\u2212', '-');
  if (text.contains('/')) {
    if (text.contains(' ')) {
      final p = text.split(' ');
      if (p.length == 2) {
        final w = int.tryParse(p[0]), fp = p[1].split('/');
        if (w != null && fp.length == 2) {
          final n = int.tryParse(fp[0]), d = int.tryParse(fp[1]);
          if (n != null && d != null && d != 0)
            return YIFraction(numerator: (w.abs() * d + n) * (w < 0 ? -1 : 1), denominator: d).simplified();
        }
      }
    }
    final p = text.split('/');
    if (p.length == 2) {
      final n = int.tryParse(p[0]), d = int.tryParse(p[1]);
      if (n != null && d != null && d != 0) return YIFraction(numerator: n, denominator: d).simplified();
    }
  }
  final iv = int.tryParse(text);
  if (iv != null) return YIFraction(numerator: iv, denominator: 1);
  final dv = double.tryParse(text);
  return dv != null ? YIFraction.fromDouble(dv) : null;
}

