// Y-INTERCEPT SOLVER
// ═══════════════════════════════════════════════════════════════════════

class YInterceptSolver {
  YInterceptSolver._();

  // ── Public API ─────────────────────────────────────────────────────

  static YIResult? tryParseAny(String input) {
    final p = _parseAnyForm(input);
    if (p == null) return null;
    final (a, b, c, type) = p;
    return _computeFromABC(a, b, c, type);
  }

  static YIResult? tryParseSlopeIntercept({required String mText, required String bText}) {
    final m = parseFractionString(mText);
    final b = parseFractionString(bText);
    if (m == null || b == null) return null;
    return _computeSlopeIntercept(m.simplified(), b.simplified());
  }

  static YIResult fromSlopeIntercept({required YIFraction m, required YIFraction b}) =>
      _computeSlopeIntercept(m.simplified(), b.simplified());

  static YIResult fromSlopeInterceptDoubles({required double m, required double b}) =>
      _computeSlopeIntercept(YIFraction.fromDouble(m), YIFraction.fromDouble(b));

  static YIResult fromStandardForm({required int A, required int B, required int C}) =>
      _computeFromABC(A, B, C, YIInputType.standardForm);

  // ── Universal Parser ──────────────────────────────────────────────

  static (int, int, int, YIInputType)? _parseAnyForm(String raw) {
    String s = raw.replaceAll('\u2212', '-').replaceAll(' ', '');
    final eqIdx = s.indexOf('=');
    if (eqIdx < 0) return null;
    final lhs = s.substring(0, eqIdx), rhs = s.substring(eqIdx + 1);

    YIFraction lA = zeroFrac, lB = zeroFrac, lC = zeroFrac;
    for (final t in _tokenise(lhs)) {
      if (t.variable == 'x') lA += t.coeff;
      else if (t.variable == 'y') lB += t.coeff;
      else lC += t.coeff;
    }
    YIFraction rA = zeroFrac, rB = zeroFrac, rC = zeroFrac;
    for (final t in _tokenise(rhs)) {
      if (t.variable == 'x') rA += t.coeff;
      else if (t.variable == 'y') rB += t.coeff;
      else rC += t.coeff;
    }

    final A = lA - rA, B = lB - rB, C = rC - lC;
    final denom = lcm(lcm(A.denominator, B.denominator), C.denominator);
    final iA = A.numerator * (denom ~/ A.denominator);
    final iB = B.numerator * (denom ~/ B.denominator);
    final iC = C.numerator * (denom ~/ C.denominator);

    final g = gcd3(iA.abs(), iB.abs(), iC.abs());
    return (g == 0 ? iA : iA ~/ g, g == 0 ? iB : iB ~/ g, g == 0 ? iC : iC ~/ g,
            _detectInputType(raw, A.numerator, B.numerator, C.numerator));
  }

  static List<_Term> _tokenise(String expr) {
    if (expr.isEmpty) return [];
    if (!expr.startsWith('-') && !expr.startsWith('+')) expr = '+$expr';
    final tokens = <String>[];
    for (int i = 1, s = 0; i <= expr.length; i++) {
      if (i == expr.length || expr[i] == '+' || expr[i] == '-') {
        tokens.add(expr.substring(s, i).trim());
        s = i;
      }
    }
    return tokens.map((t) => _parseTerm(t)).whereType<_Term>().toList();
  }

  static _Term? _parseTerm(String tok) {
    tok = tok.trim();
    if (tok.isEmpty) return null;
    int sign = 1;
    if (tok.startsWith('-')) { sign = -1; tok = tok.substring(1).trim(); }
    else if (tok.startsWith('+')) { tok = tok.substring(1).trim(); }

    final hasX = tok.toLowerCase().contains('x');
    final hasY = tok.toLowerCase().contains('y');
    if (hasX && hasY) return null;

    String varName = 'const', coeffStr = tok;
    if (hasX) { varName = 'x'; coeffStr = tok.toLowerCase().replaceAll('x', '').replaceAll('*', '').trim(); }
    else if (hasY) { varName = 'y'; coeffStr = tok.toLowerCase().replaceAll('y', '').replaceAll('*', '').trim(); }

    YIFraction coeff;
    if (coeffStr.isEmpty) {
      coeff = oneFrac;
    } else if (coeffStr.contains('/')) {
      final p = coeffStr.split('/');
      if (p.length != 2) return null;
      final n = int.tryParse(p[0].trim()), d = int.tryParse(p[1].trim());
      if (n == null || d == null || d == 0) return null;
      coeff = YIFraction(numerator: n, denominator: d).simplified();
    } else {
      final n = int.tryParse(coeffStr);
      if (n != null) { coeff = YIFraction(numerator: n, denominator: 1); }
      else { final d = double.tryParse(coeffStr); if (d == null) return null; coeff = YIFraction.fromDouble(d); }
    }

    return _Term(
      variable: varName,
      coeff: YIFraction(numerator: sign * coeff.numerator, denominator: coeff.denominator).simplified(),
    );
  }

  static YIInputType _detectInputType(String raw, int A, int B, int C) {
    final s = raw.replaceAll(' ', '').toLowerCase();
    if (s.endsWith('=0')) return YIInputType.generalForm;
    if (s.startsWith('y=')) return YIInputType.slopeIntercept;
    return YIInputType.standardForm;
  }

  // ── Core Computation ──────────────────────────────────────────────

  static YIResult _computeFromABC(int A, int B, int C, YIInputType type) {
    final sfStr = sfString(A, B, C), gfStr = generalFormFromABC(A, B, C);
    final sfTex = sfLatex(A, B, C), gfTex = gfLatex(A, B, -C);

    if (B == 0) {
      if (A == 0) return YIResult(
        yIntercept: null, xIntercept: null,
        generalForm: gfStr, standardForm: sfStr, slope: null,
        equation: C == 0 ? 'All real numbers' : 'No solution',
        direction: 'N/A', angle: 'N/A', riseRun: 'N/A', inputType: type,
        slopeStepsFromStandard: const [], slopeStepsFromGeneral: const [],
        xInterceptSteps: const [], standardFormSteps: const [], generalFormSteps: const [],
      );
      final xVal = YIFraction(numerator: C, denominator: A).simplified();
      return YIResult(
        yIntercept: null, xIntercept: xVal,
        generalForm: gfStr, standardForm: sfStr, slope: null,
        equation: 'x = $xVal', direction: 'Vertical |', angle: '90.0\u00b0',
        riseRun: 'Undefined', inputType: type,
        slopeStepsFromStandard: buildVerticalSlopeSteps(A, C, sfTex, gfTex),
        slopeStepsFromGeneral: buildVerticalSlopeSteps(A, C, sfTex, gfTex),
        xInterceptSteps: buildVerticalXSteps(A, C, xVal),
        standardFormSteps: [], generalFormSteps: [],
      );
    }

    final m = YIFraction(numerator: -A, denominator: B).simplified();
    final b = YIFraction(numerator: C, denominator: B).simplified();
    final eqTex = eqLatex(m, b);
    final xInt = m.isZero ? null : (b * negOneFrac).divided(m).simplified();
    final angleVal = atan(m.toDouble()) * 180 / pi;

    return YIResult(
      yIntercept: b, xIntercept: xInt,
      generalForm: gfStr, standardForm: sfStr, slope: m, equation: eqTex,
      direction: direction(m.toDouble()),
      angle: '${angleVal.toStringAsFixed(1)}\u00b0',
      riseRun: riseRun(m), inputType: type,
      slopeStepsFromStandard: buildSlopeStepsFromStandard(A, B, C, m, b, sfTex, gfTex, eqTex),
      slopeStepsFromGeneral: buildSlopeStepsFromGeneral(A, B, C, m, b, sfTex, gfTex, eqTex),
      xInterceptSteps: buildXInterceptSteps(m, b, xInt),
      standardFormSteps: buildStandardFormSteps(A, B, C, gfTex, sfTex),
      generalFormSteps: buildGeneralFormSteps(A, B, C, sfTex, gfTex),
    );
  }

  static YIResult _computeSlopeIntercept(YIFraction m, YIFraction b) {
    final ms = m.simplified(), bs = b.simplified();
    final eqTex = eqLatex(ms, bs);
    final sfStr = standardFormFromSlopeIntercept(ms, bs);
    final gfStr = generalFormFromSlopeIntercept(ms, bs);
    final sfTex = sfTexFromSlopeIntercept(ms, bs);
    final gfTex = gfTexFromSlopeIntercept(ms, bs);
    final xInt = ms.isZero ? null : (bs * negOneFrac).divided(ms).simplified();
    final angleVal = atan(ms.toDouble()) * 180 / pi;

    return YIResult(
      yIntercept: bs, xIntercept: xInt,
      generalForm: gfStr, standardForm: sfStr,
      slope: ms, equation: eqTex,
      direction: direction(ms.toDouble()),
      angle: '${angleVal.toStringAsFixed(1)}\u00b0',
      riseRun: riseRun(ms), inputType: YIInputType.slopeIntercept,
      slopeStepsFromStandard: buildSlopeInterceptDirectSteps(ms, bs, eqTex, sfTex, gfTex),
      slopeStepsFromGeneral: buildSlopeInterceptDirectSteps(ms, bs, eqTex, sfTex, gfTex),
      xInterceptSteps: buildXInterceptSteps(ms, bs, xInt),
      standardFormSteps: buildStandardFormFromSlopeInterceptSteps(ms, bs, sfTex, gfTex),
      generalFormSteps: buildGeneralFormFromSlopeInterceptSteps(ms, bs, sfTex, gfTex),
    );
  }
}

