// PARALLEL / PERPENDICULAR SOLVER
// ═══════════════════════════════════════════════════════════════════════

class ParallelPerpendicularSolver {
  ParallelPerpendicularSolver._();

  static PPResult? tryParse({required String line1, required String line2}) {
    final l1 = _parseLine(line1), l2 = _parseLine(line2);
    if (l1 == null || l2 == null) return null;
    return _compute(l1, l2);
  }

  static _Line? _parseLine(String raw) {
    final s = raw.replaceAll('\u2212', '-').replaceAll(' ', '').toLowerCase();
    final eqIdx = s.indexOf('=');
    if (eqIdx < 0) return null;
    int A = 0, B = 0, C = 0;

    void add(String expr, int sign) {
      final e = expr.isEmpty ? '' : (expr[0] != '-' ? '+$expr' : expr);
      final re = RegExp(r'[+\-][^+\-]+');
      for (final m in re.allMatches(e)) {
        final tok = m.group(0)!;
        final tokSign = tok[0] == '-' ? -1 : 1;
        final body = tok.substring(1);
        if (body.contains('x')) A += sign * tokSign * _coeff(body.replaceAll('x', ''));
        else if (body.contains('y')) B += sign * tokSign * _coeff(body.replaceAll('y', ''));
        else { final v = int.tryParse(body); if (v == null) return; C += sign * tokSign * v; }
      }
    }

    add(s.substring(0, eqIdx), 1);
    add(s.substring(eqIdx + 1), -1);
    if (A == 0 && B == 0) return null;
    return _Line(A: A, B: B, C: C, display: '${A}x + ${B}y + $C = 0');
  }

  static int _coeff(String raw) {
    if (raw.isEmpty || raw == '+') return 1;
    if (raw == '-') return -1;
    return int.tryParse(raw) ?? 1;
  }

  static _SIResult _toSI(_Line l) {
    if (l.B == 0) {
      final xv = YIFraction(numerator: -l.C, denominator: l.A).simplified();
      return _SIResult(slope: null, yInt: null, equation: 'x = $xv',
          latexEquation: 'x = ${fracLatex(xv)}', isVertical: true);
    }
    final m = YIFraction(numerator: -l.A, denominator: l.B).simplified();
    final b = YIFraction(numerator: -l.C, denominator: l.B).simplified();
    return _SIResult(slope: m, yInt: b, equation: _siStr(m, b),
        latexEquation: _siLatex(m, b), isVertical: false);
  }

  static String _siStr(YIFraction m, YIFraction b) {
    if (m.isZero) return 'y = $b';
    final mp = m == oneFrac ? 'x' : m == negOneFrac ? '-x' : '${m}x';
    if (b.isZero) return 'y = $mp';
    return b.numerator > 0 ? 'y = $mp + $b' : 'y = $mp - ${b.abs()}';
  }

  static String _siLatex(YIFraction m, YIFraction b) {
    if (m.isZero) return 'y = ${fracLatex(b)}';
    final mp = m == oneFrac ? 'x' : m == negOneFrac ? '-x' : '${fracLatex(m)}x';
    if (b.isZero) return 'y = $mp';
    return b.numerator > 0 ? 'y = $mp + ${fracLatex(b)}' : 'y = $mp - ${fracLatex(b.abs())}';
  }

  static PPRelationship _classify(_SIResult s1, _SIResult s2) {
    if (s1.isVertical && s2.isVertical) return s1.equation == s2.equation ? PPRelationship.sameLine : PPRelationship.parallel;
    if (s1.isVertical || s2.isVertical) return PPRelationship.neither;
    final m1 = s1.slope!, m2 = s2.slope!;
    if (m1 == m2) return (s1.yInt != null && s2.yInt != null && s1.yInt == s2.yInt) ? PPRelationship.sameLine : PPRelationship.parallel;
    return (m1 * m2).simplified().numerator == -(m1 * m2).simplified().denominator ? PPRelationship.perpendicular : PPRelationship.neither;
  }

  // ── Computation + Step Building ───────────────────────────────────

  static PPResult _compute(_Line l1, _Line l2) {
    final steps = <PPSolverStep>[];
    final si1 = _toSI(l1), si2 = _toSI(l2);
    final m1Str = si1.slope == null ? 'undefined' : fracLatex(si1.slope!);
    final m2Str = si2.slope == null ? 'undefined' : fracLatex(si2.slope!);
    final rel = _classify(si1, si2);
    final vStr = _verdictString(rel), vSym = _verdictSymbol(rel);

    String lineToLatex(_Line l) => '${l.A}x ${l.B >= 0 ? '+' : '-'} ${l.B.abs()}y ${l.C >= 0 ? '+' : '-'} ${l.C.abs()} = 0';

    // Step 1: Identify lines
    steps.add(PPSolverStep(number: 1, title: 'Identify the equations', blocks: [
      const PPStepBlock(type: PPBlockType.note, content: 'Rewrite each equation in general form to identify A, B, C.'),
      const PPStepBlock(type: PPBlockType.formula, latex: r'Ax + By + C = 0', label: 'General form'),
      PPStepBlock(type: PPBlockType.substitution, label: 'Line 1', latex: '${lineToLatex(l1)} \\Rightarrow A_1=${l1.A}, B_1=${l1.B}, C_1=${l1.C}'),
      PPStepBlock(type: PPBlockType.substitution, label: 'Line 2', latex: '${lineToLatex(l2)} \\Rightarrow A_2=${l2.A}, B_2=${l2.B}, C_2=${l2.C}'),
    ]));

    // Step 2-3: Convert to slope-intercept
    steps.addAll(_buildSISteps(l1, si1, l2, si2));

    // Step: Compare slopes
    steps.add(PPSolverStep(number: 3, title: 'Extract and compare slopes', blocks: [
      const PPStepBlock(type: PPBlockType.note, content: 'The slope is the coefficient of x after isolating y.'),
      const PPStepBlock(type: PPBlockType.formula, latex: r'y = mx + b \quad\Rightarrow\quad \text{slope} = m'),
      PPStepBlock(type: PPBlockType.substitution, label: 'Line 1', latex: '${si1.latexEquation} \\Rightarrow m_1 = $m1Str'),
      PPStepBlock(type: PPBlockType.substitution, label: 'Line 2', latex: '${si2.latexEquation} \\Rightarrow m_2 = $m2Str'),
      PPStepBlock(type: PPBlockType.result, latex: 'm_1 = $m1Str \\qquad m_2 = $m2Str'),
    ]));

    // Step: Relationship test + conclusion
    steps.addAll(_buildTestAndConclusion(rel, si1, si2, m1Str, m2Str));

    return PPResult(
      slope1: si1.slope, slope2: si2.slope,
      yIntercept1: si1.yInt, yIntercept2: si2.yInt,
      slopeIntercept1: si1.equation, slopeIntercept2: si2.equation,
      relationship: rel, verdict: vStr, verdictSymbol: vSym,
      steps: steps,
      a1: l1.A, b1: l1.B, c1: l1.C,
      a2: l2.A, b2: l2.B, c2: l2.C,
    );
  }

  static List<PPSolverStep> _buildSISteps(_Line l1, _SIResult si1, _Line l2, _SIResult si2) {
    PPSolverStep one(_Line l, _SIResult si, int num, String label) {
      if (l.B == 0) {
        return PPSolverStep(number: num, title: 'Convert $label to slope-intercept', groupKey: 'si',
          blocks: [
            PPStepBlock(type: PPBlockType.note, content: 'B=0, no y-term. Vertical line with undefined slope.'),
            const PPStepBlock(type: PPBlockType.formula, latex: r'B = 0 \;\Rightarrow\; Ax + C = 0 \;\Rightarrow\; x = -\tfrac{C}{A}', label: 'Vertical line rule'),
            PPStepBlock(type: PPBlockType.substitution, latex: '${l.A}x + (${l.C}) = 0 \\\\[4pt] ${l.A}x = ${-l.C} \\\\[4pt] x = \\dfrac{${-l.C}}{${l.A}}'),
            PPStepBlock(type: PPBlockType.result, latex: si.latexEquation, content: '${si.equation}'),
          ]);
      }
      final mFrac = YIFraction(numerator: -l.A, denominator: l.B).simplified();
      final bFrac = YIFraction(numerator: -l.C, denominator: l.B).simplified();
      return PPSolverStep(number: num, title: 'Convert $label to slope-intercept', groupKey: 'si',
        blocks: [
          PPStepBlock(type: PPBlockType.note, content: 'Isolate y, then divide every term by B=${l.B}.'),
          const PPStepBlock(type: PPBlockType.formula, latex: r'Ax + By + C = 0 \;\Rightarrow\; y = -\dfrac{A}{B}x - \dfrac{C}{B}', label: 'Formula'),
          PPStepBlock(type: PPBlockType.substitution, latex: '${l.A}x + ${l.B}y + ${l.C} = 0 \\\\[4pt] ${l.B}y = ${-l.A}x + ${-l.C} \\\\[4pt] y = \\dfrac{${-l.A}}{${l.B}}x + \\dfrac{${-l.C}}{${l.B}}'),
          PPStepBlock(type: PPBlockType.working, latex: 'm = ${fracLatex(mFrac)} \\\\[4pt] b = ${fracLatex(bFrac)}'),
          PPStepBlock(type: PPBlockType.result, latex: si.latexEquation, content: si.equation),
        ]);
    }
    return [one(l1, si1, 2, 'Line 1'), one(l2, si2, 2, 'Line 2')];
  }

  static List<PPSolverStep> _buildTestAndConclusion(
    PPRelationship rel, _SIResult si1, _SIResult si2, String m1Str, String m2Str,
  ) {
    final m1T = si1.slope != null ? fracLatex(si1.slope!) : r'\text{undefined}';
    final m2T = si2.slope != null ? fracLatex(si2.slope!) : r'\text{undefined}';

    PPSolverStep testStep(int n, String title, List<PPStepBlock> blocks) =>
        PPSolverStep(number: n, title: title, blocks: blocks);

    final steps = <PPSolverStep>[];

    if (rel == PPRelationship.parallel) {
      final b1T = si1.yInt != null ? fracLatex(si1.yInt!) : '---';
      final b2T = si2.yInt != null ? fracLatex(si2.yInt!) : '---';
      steps.add(testStep(4, 'Apply parallel test', [
        const PPStepBlock(type: PPBlockType.note, content: 'Parallel lines have equal slopes but different y-intercepts.'),
        const PPStepBlock(type: PPBlockType.formula, latex: r'm_1 = m_2 \quad\text{and}\quad b_1 \neq b_2', label: 'Condition'),
        PPStepBlock(type: PPBlockType.substitution, latex: 'm_1 = $m1T = m_2 \\;\\checkmark \\\\[4pt] b_1 = $b1T \\neq b_2 = $b2T \\;\\checkmark'),
        const PPStepBlock(type: PPBlockType.result, latex: r'\text{Lines are } \textbf{PARALLEL} \;(\parallel)'),
      ]));
    } else if (rel == PPRelationship.perpendicular) {
      final product = (si1.slope! * si2.slope!).simplified();
      steps.add(testStep(4, 'Apply perpendicular test', [
        const PPStepBlock(type: PPBlockType.note, content: 'Perpendicular lines have slopes whose product is -1.'),
        const PPStepBlock(type: PPBlockType.formula, latex: r'm_1 \times m_2 = -1', label: 'Condition'),
        PPStepBlock(type: PPBlockType.substitution, latex: '($m1T) \\times ($m2T) = ${fracLatex(product)} = -1 \\;\\checkmark'),
        const PPStepBlock(type: PPBlockType.result, latex: r'\text{Lines are } \textbf{PERPENDICULAR} \;(\perp)'),
      ]));
    } else if (rel == PPRelationship.sameLine) {
      steps.add(testStep(4, 'Apply coincident test', [
        const PPStepBlock(type: PPBlockType.note, content: 'Same slopes AND same y-intercepts means the lines are identical.'),
        const PPStepBlock(type: PPBlockType.formula, latex: r'm_1 = m_2 \quad\text{and}\quad b_1 = b_2', label: 'Condition'),
        PPStepBlock(type: PPBlockType.substitution, latex: 'm_1 = $m1T = m_2 \\;\\checkmark \\\\[4pt] b_1 = b_2 \\;\\checkmark'),
        const PPStepBlock(type: PPBlockType.result, latex: r'\text{Lines are the } \textbf{SAME LINE} \;(\equiv)'),
      ]));
    } else {
      final product = si1.slope != null && si2.slope != null
          ? (si1.slope! * si2.slope!).simplified() : null;
      final pT = product != null ? fracLatex(product) : 'undefined';
      steps.add(testStep(4, 'Apply both tests', [
        const PPStepBlock(type: PPBlockType.note, content: 'Check if slopes are equal (parallel) or product = -1 (perpendicular).'),
        const PPStepBlock(type: PPBlockType.formula, latex: r'\text{Parallel: } m_1 = m_2 \qquad \text{Perp: } m_1 \times m_2 = -1'),
        PPStepBlock(type: PPBlockType.substitution, latex: 'm_1 = $m1T, m_2 = $m2T'),
        PPStepBlock(type: PPBlockType.working, latex: '\\text{Parallel? } $m1T \\neq $m2T \\;\\times \\\\[4pt] \\text{Perp? } $m1T \\times $m2T = $pT \\neq -1 \\;\\times'),
        const PPStepBlock(type: PPBlockType.result, latex: r'\text{Lines are } \textbf{NEITHER}'),
      ]));
    }

    // Conclusion
    steps.add(PPSolverStep(number: 5, title: 'Conclusion', blocks: [
      PPStepBlock(type: PPBlockType.note, content: _verdictExplanation(rel)),
      PPStepBlock(type: PPBlockType.result,
          latex: '\\textbf{${_verdictSymbol(rel)}\\;\\text{Lines are ${_verdictString(rel).replaceAll(' ', '\\ ')}}}',
          content: '${_verdictSymbol(rel)} The lines are ${_verdictString(rel)}.'),
    ]));

    return steps;
  }

  static String _verdictString(PPRelationship r) {
    switch (r) {
      case PPRelationship.parallel: return 'Parallel';
      case PPRelationship.perpendicular: return 'Perpendicular';
      case PPRelationship.sameLine: return 'Same Line';
      case PPRelationship.neither: return 'Neither';
    }
  }

  static String _verdictSymbol(PPRelationship r) {
    switch (r) {
      case PPRelationship.parallel: return '\u2225';
      case PPRelationship.perpendicular: return '\u22a5';
      case PPRelationship.sameLine: return '\u2261';
      case PPRelationship.neither: return '\u2226';
    }
  }

  static String _verdictExplanation(PPRelationship r) {
    switch (r) {
      case PPRelationship.parallel: return 'Equal slopes, different y-intercepts. Lines never meet.';
      case PPRelationship.perpendicular: return 'Slopes are negative reciprocals (product = -1). Lines cross at 90\u00b0.';
      case PPRelationship.sameLine: return 'Both slopes and y-intercepts are identical. Lines overlap completely.';
      case PPRelationship.neither: return 'Neither condition is satisfied. Lines intersect at an oblique angle.';
    }
  }
}
